<?php
 namespace QQWorld\Setup\Fixtures\FixturesAsserts; class ConfigurableProductsAssert { private $productRepository; private $optionRepository; private $productAssert; public function __construct( \QQWorld\Catalog\Api\ProductRepositoryInterface $productRepository, \QQWorld\ConfigurableProduct\Api\OptionRepositoryInterface $optionRepository, \QQWorld\Setup\Fixtures\FixturesAsserts\ProductAssert $productAssert ) { $this->productRepository = $productRepository; $this->optionRepository = $optionRepository; $this->productAssert = $productAssert; } public function assert() { $productsMap = [ 'Configurable Product - Default %s' => [ 'attributes' => 1, 'options' => 3, 'amount' => 2, ], 'Configurable Product - Color-Size %s' => [ 'attributes' => 2, 'options' => 3, 'amount' => 2, ], 'Configurable Product 2-2 %s' => [ 'attributes' => 2, 'options' => 2, 'amount' => 2, ], ]; foreach ($productsMap as $skuPattern => $expectedData) { $configurableSku = sprintf($skuPattern, 1); $product = $this->productRepository->get($configurableSku); $this->productAssert->assertProductsCount($skuPattern, $expectedData['amount']); $this->productAssert->assertProductType('configurable', $product); $options = $this->optionRepository->getList($configurableSku); if ($expectedData['attributes'] !== count($options)) { throw new \AssertionError('Configurable options amount is wrong'); } if ($expectedData['options'] !== count($options[0]->getValues())) { throw new \AssertionError('Configurable option values amount is wrong'); } } } } 